def ears_are_skin():
    """The generated texture shades the ears dark brown, so they classify as hair and get its strands: what faces
    sideways inside the box of MPFB's ears (the head is fitted to them), a little grown, is skin."""
    gi = h.vertex_groups['ears'].index
    dg = bpy.context.evaluated_depsgraph_get()
    me = h.evaluated_get(dg).to_mesh()
    pts = np.array([v.co[:] for v, src in zip(me.vertices, h.data.vertices)
                    if any(g.group == gi and g.weight > 0.5 for g in src.groups)])
    h.evaluated_get(dg).to_mesh_clear()
    kd = KDTree(len(pts))  # near the ears themselves, not just in their box (that took in the hair over them)
    for i, q in enumerate(pts):
        kd.insert(q, i)
    kd.balance()
    n = e = 0
    for side in (1, -1):
        p = pts[pts[:, 0] * side > 0]
        lo, hi = p.min(0) - EAR_GROW, p.max(0) + EAR_GROW
        for f in gbm.faces:
            c = f.calc_center_median()
            inside = (lo <= np.array(c)).all() and (np.array(c) <= hi).all()
            if inside and f.normal.x * side > EAR_FACING and kd.find(c)[2] < EAR_NEAR:
                f[EAR] = 1
                e += 1
                n += f[CLS] == head_shape.HAIR
    # their class stays: MPFB's right ear sits over the generated one, in the hair - made skin, the hair there came
    # out as a pale patch; the ears get their colour on the head (ear_surroundings)
    print('ears: %d faces (%d of them hair)' % (e, n))


