def is_hair(f):
    return f[CLS] == head_shape.HAIR


def is_skin(f):
    return f[CLS] == head_shape.SKIN


def interp(pts, x):
    for (x0, y0), (x1, y1) in zip(pts, pts[1:]):
        if min(x0, x1) <= x <= max(x0, x1):
            return y0 + (y1 - y0) * (x - x0) / ((x1 - x0) or 1)
    return None


def drop_loose():
    """Pieces wholly under the chin (bits of the generated collar)."""
    seen, comps = set(), []
    for f in gbm.faces:
        if f in seen:
            continue
        comp, stack = [], [f]; seen.add(f)
        while stack:
            g = stack.pop(); comp.append(g)
            for e in g.edges:
                for k in e.link_faces:
                    if k not in seen:
                        seen.add(k); stack.append(k)
        comps.append(comp)
    for comp in comps:
        if all(f.calc_center_median().z < CHIN_Z for f in comp):
            bmesh.ops.delete(gbm, geom=comp, context='FACES')
    bmesh.ops.delete(gbm, geom=[v for v in gbm.verts if not v.link_faces], context='VERTS')


def cut_neck():
    """Under the chin the generated head is its uniform's collar and shirt: cut off by a plane NECK_CUT under the chin,
    with what is uniform-coloured or pale skin under the jaw; the opening capped (material 1: no texture) - the remesh
    needs a closed surface, and the neck runs up into the cap."""
    co, no = Vector((0, 0, CHIN_Z - NECK_CUT)), Vector((0, 0, 1))
    bmesh.ops.delete(gbm, geom=[f for f in gbm.faces if f[CLS] == head_shape.COLLAR or (
        f[UNIFORM] and f.calc_center_median().z < CHIN_Z + 0.01) or (
        f[CLS] == head_shape.SKIN and f.calc_center_median().z < CHIN_Z - 0.004)], context='FACES')
    bmesh.ops.bisect_plane(gbm, geom=gbm.verts[:] + gbm.edges[:] + gbm.faces[:], dist=1e-6,
                           plane_co=co, plane_no=no, clear_inner=True)
    bmesh.ops.triangulate(gbm, faces=[f for f in gbm.faces if len(f.verts) > 3])
    bmesh.ops.delete(gbm, geom=[v for v in gbm.verts if not v.link_faces], context='VERTS')
    drop_loose()
    for _ in range(RIM_SPIKES):  # spikes along the rim (faces with two open edges) off
        spikes = [f for f in gbm.faces if sum(e.is_boundary for e in f.edges) >= 2
                  and all(v.co.z < CHIN_Z + 0.03 for v in f.verts)]
        if not spikes:
            break
        bmesh.ops.delete(gbm, geom=spikes, context='FACES')
        bmesh.ops.delete(gbm, geom=[v for v in gbm.verts if not v.link_faces], context='VERTS')
    # the cap takes the class of the rim round it: under the whiskers it is the beard's underside (hair), under the
    # chin skin (all skin, the whiskers' underside was a flat pale shelf between the beard and the collar)
    rim = [(v.co.copy(), any(f[CLS] == head_shape.HAIR for f in v.link_faces))
           for v in {v for e in gbm.edges if e.is_boundary for v in e.verts}]
    kd = KDTree(len(rim))
    for i, (q, _) in enumerate(rim):
        kd.insert(q, i)
    kd.balance()
    cap = bmesh.ops.holes_fill(gbm, edges=[e for e in gbm.edges if e.is_boundary], sides=0)['faces']
    cap = bmesh.ops.triangulate(gbm, faces=cap)['faces']
    n_hair = 0
    for f in cap:
        near = kd.find_n(f.calc_center_median(), 6)
        hair = sum(rim[i][1] for _, i, _ in near) * 2 > len(near)
        f[CLS] = head_shape.HAIR if hair else head_shape.SKIN
        n_hair += hair
        f.material_index = 1
    bmesh.ops.recalc_face_normals(gbm, faces=gbm.faces[:])
    gbm.normal_update()
    print('neck cut: %d cap faces (%d under the beard)' % (len(cap), n_hair))


cut_neck()


def bary(p, a, b, c):
    """Barycentric weights of p's projection onto the plane of a, b, c (unclamped: a point just outside extrapolates)."""
    v0, v1, v2 = b - a, c - a, p - a
    d00, d01, d11, d20, d21 = v0.dot(v0), v0.dot(v1), v1.dot(v1), v2.dot(v0), v2.dot(v1)
    den = d00 * d11 - d01 * d01
    if abs(den) < 1e-18:
        return 1.0, 0.0, 0.0
    y = (d11 * d20 - d01 * d21) / den
    z = (d00 * d21 - d01 * d20) / den
    return 1 - y - z, y, z


def mirror_jaw():
    """His left's jaw and whisker made his right's mirror image: generated, the left whisker hung down to the collar,
    narrow, while the right one flares out over the neck with the jaw's line rising to the ear (the user's choice of
    the two). The block x > MIRROR_JAW[0], z < CHIN_Z + MIRROR_JAW[1] is cut out and the right's block, mirrored over
    x = 0, put in its place (each closed by a cap inside it; the remesh unites them); his left's surface round the
    block is drawn onto the mirrored right's over MIRROR_JAW[2], so the seams meet. The mirrored faces take the colour
    of his left's own surface where they stand (with the right whisker's, the block was a dark patch with a straight
    edge under the paler left sideburn and the hair behind the ear)."""
    x0, z1, band = MIRROR_JAW[0], CHIN_Z + MIRROR_JAW[1], MIRROR_JAW[2]
    mvs = [Vector((-v.co.x, v.co.y, v.co.z)) for v in gbm.verts]
    gbm.verts.index_update()
    mirrored = BVHTree.FromPolygons(mvs, [[v.index for v in f.verts][::-1] for f in gbm.faces])
    mirrored_cls = [f[CLS] for f in gbm.faces]
    for co, no in (((0, 0, z1), (0, 0, 1)), ((x0, 0, 0), (1, 0, 0)), ((-x0, 0, 0), (1, 0, 0))):
        # only round the blocks (the planes x = +-x0 run through the eyes)
        near = [f for f in gbm.faces if min(v.co.z for v in f.verts) < z1 + 0.005
                and max(abs(v.co.x) for v in f.verts) > x0 - 0.005]
        geom = list({e for f in near for e in f.edges}) + near + list({v for f in near for v in f.verts})
        bmesh.ops.bisect_plane(gbm, geom=geom, dist=1e-6, plane_co=co, plane_no=no)
    bmesh.ops.triangulate(gbm, faces=[f for f in gbm.faces if len(f.verts) > 3])

    def in_block(f, s):
        c = f.calc_center_median()
        return c.x * s > x0 and c.z < z1
    right = [f for f in gbm.faces if in_block(f, -1)]
    left = [f for f in gbm.faces if in_block(f, 1)]
    # the left's surface round the block onto the mirrored right's (the block's own goes)
    moved = 0
    for v in gbm.verts:
        if v.co.x < x0 - band or v.co.z > z1 + band:
            continue
        w = (1 - smoothstep(v.co.z, z1, z1 + band)) * smoothstep(v.co.x, x0 - band, x0)
        if w <= 0 or any(f[EAR] for f in v.link_faces):
            continue
        loc = mirrored.find_nearest(v.co)[0]
        if loc is not None:
            v.co = v.co.lerp(loc, w)
            moved += 1
    # ... and hair where the right is (his right ear sits 6 mm lower: its whisker reaches up to the lobe; drawn out to
    # it, the left's skin under its lobe was a pale band over the whisker)
    n_hair = 0
    for f in gbm.faces:
        c = f.calc_center_median()
        w = (1 - smoothstep(c.z, z1, z1 + band)) * smoothstep(c.x, x0 - band, x0)
        if 0.3 < w and not in_block(f, 1) and not f[EAR] and f[CLS] != head_shape.HAIR:
            if mirrored_cls[mirrored.find_nearest(c)[2]] == head_shape.HAIR:
                f[CLS] = head_shape.HAIR
                n_hair += 1
    uvl = gbm.loops.layers.uv['UVMap']
    gbm.faces.index_update()
    own = BVHTree.FromBMesh(gbm)  # his left as it was, for the colour
    own_f = [([v.co.copy() for v in f.verts], [l[uvl].uv.copy() for l in f.loops], [l[puv].uv.copy() for l in f.loops])
             for f in gbm.faces]
    dup = bmesh.ops.duplicate(gbm, geom=right)
    piece = [g for g in dup['geom'] if isinstance(g, bmesh.types.BMFace)]
    for v in {v for f in piece for v in f.verts}:
        v.co.x = -v.co.x
    bmesh.ops.reverse_faces(gbm, faces=piece)
    gbm.normal_update()
    for f in piece:  # the colour of his left's own surface nearest it: each face from one face of it (a face's corners
        # from different faces spanned other islands of the texture), its corners' places in that face's plane
        k = own.find_nearest(f.calc_center_median())[2]
        co, uv, pj = own_f[k]
        for l in f.loops:
            w = bary(l.vert.co, *co)
            l[uvl].uv = uv[0] * w[0] + uv[1] * w[1] + uv[2] * w[2]
            l[puv].uv = pj[0] * w[0] + pj[1] * w[1] + pj[2] * w[2]
            l[FACING].uv = (l.vert.normal.dot(FWD), 0.0)
    bmesh.ops.delete(gbm, geom=left, context='FACES')
    bmesh.ops.delete(gbm, geom=[v for v in gbm.verts if not v.link_faces], context='VERTS')
    gbm.normal_update()
    caps = bmesh.ops.holes_fill(gbm, edges=[e for e in gbm.edges if e.is_boundary], sides=0)['faces']
    caps = bmesh.ops.triangulate(gbm, faces=caps)['faces']
    for f in caps:  # inside the union: no rim (material 0, not the cut's cap)
        f[CLS] = head_shape.SKIN; f[UNIFORM] = 0; f[EAR] = 0; f.material_index = 0
        for l in f.loops:  # no area in the texture (holes_fill's UVs spanned islands of the face: patches all over it)
            l[uvl].uv = l[puv].uv = (0.0, 0.0)
    gbm.normal_update()  # (the caps' orientation does not matter to the remesh)
    print('jaw mirrored: %d faces of his right put in for %d of his left, %d round them drawn on (%d made hair), '
          '%d cap faces' % (len(piece), len(left), moved, n_hair, len(caps)))


mirror_jaw()


def blur(a, r):
    for ax in (0, 1):
        pad = [(r + 1, r) if i == ax else (0, 0) for i in range(a.ndim)]
        c = np.cumsum(np.pad(a, pad, mode='edge'), axis=ax)
        n = c.shape[ax]
        a = (np.take(c, range(2 * r + 1, n), axis=ax) - np.take(c, range(0, n - 2 * r - 1), axis=ax)) / (2 * r + 1)
    return a


def np_smooth(x, a, b):
    t = np.clip((x - a) / (b - a), 0, 1)
    return t * t * (3 - 2 * t)


def face_relief():
    """His left upper face as deep as his right: generated from the portrait's three-quarter view as if it were the
    front, the side turned to the viewer (his left) came out forward of the right's mirror image - the forehead 1-3 mm,
    the cheek 4-5, the eye, its lids and the bags under it 7-11 (the nose stood out much less beside that eye, its lid
    looked puffed up). Over the forehead, brows, eyes and cheeks (FACE_RELIEF_X / _Z; not the nose, mouth or beard)
    his left goes back to the right's mirror image's depth, never forward. The vertices move along the portrait's view
    axis only, so the picture on them stays where it was."""
    img = img_points(gbm)
    gbm.normal_update()
    front = [v for v in gbm.verts if v.normal.dot(FWD) > 0.3]
    c = min(front, key=lambda v: (img[v][0] - FACE_RELIEF_EYE[0]) ** 2 + (img[v][1] - FACE_RELIEF_EYE[1]) ** 2).co
    own = BVHTree.FromBMesh(gbm)
    mirrored = BVHTree.FromPolygons([Vector((-v.co.x, v.co.y, v.co.z)) for v in gbm.verts],
                                    [[v.index for v in f.verts][::-1] for f in gbm.faces])
    x0, x0n, x1, xf = FACE_RELIEF_X
    z0, zn, z1 = (c.z + q for q in FACE_RELIEF_Z[:3])
    zf = FACE_RELIEF_Z[3]
    step = 0.001
    xs = np.arange(x0 - xf, x1 + xf + step / 2, step)
    zs = np.arange(z0 - zf, z1 + zf + step / 2, step)
    diff = np.zeros((len(zs), len(xs)), np.float32)  # m his left stands forward of the right's mirror image
    ok = np.zeros_like(diff)
    for i, z in enumerate(zs):
        for j, x in enumerate(xs):
            a, na = own.ray_cast(Vector((x, -0.5, z)), Vector((0, 1, 0)), 1.0)[:2]
            b, nb = mirrored.ray_cast(Vector((x, -0.5, z)), Vector((0, 1, 0)), 1.0)[:2]
            # only where both face forward (rays through the generation's flakes and folds edge-on gave spikes:
            # small dents and cracks over the cheek)
            if a is not None and b is not None and na.y < -0.4 and nb.y < -0.4:
                diff[i, j] = min(max(b.y - a.y, 0.0), FACE_RELIEF_MAX)  # back only
                ok[i, j] = 1.0
    r = max(1, int(round(FACE_RELIEF_BLUR / step)))
    diff = blur(blur(diff, r), r) / np.maximum(blur(blur(ok, r), r), 1e-3)  # the gaps from round them
    X, Z = np.meshgrid(xs, zs)
    inner = np.where(Z < zn, x0n, x0)
    w = (np_smooth(X, inner - xf, inner) * (1 - np_smooth(X, x1, x1 + xf))
         * np_smooth(Z, z0 - zf, z0) * (1 - np_smooth(Z, z1, z1 + zf)))
    shift = diff * w
    an, ax, az, fn, fx = FACE_RELIEF_EYE_ZONE
    i0, j0 = int(round((c.z - zs[0]) / step)), int(round((c.x - xs[0]) / step))
    d_eye = float(shift[i0, j0])
    nose = X < c.x
    e = np.hypot((X - c.x) / np.where(nose, an, ax), (Z - c.z) / az)
    we = 1 - np.where(nose, np_smooth(e, 1.0, fn), np_smooth(e, 1.0, fx))
    shift = blur(blur((shift * (1 - we) + d_eye * we).astype(np.float32), r), r)

    def at(p):
        fx, fz = (p.x - xs[0]) / step, (p.z - zs[0]) / step
        if not (0 <= fx < len(xs) - 1 and 0 <= fz < len(zs) - 1):
            return 0.0
        j, i = int(fx), int(fz)
        tx, tz = fx - j, fz - i
        return float((shift[i, j] * (1 - tx) + shift[i, j + 1] * tx) * (1 - tz)
                     + (shift[i + 1, j] * (1 - tx) + shift[i + 1, j + 1] * tx) * tz)
    moved, most = 0, 0.0
    back = FWD / -FWD.y  # along the view axis, 1 m back per 1 m of depth
    for v in gbm.verts:
        d = at(v.co)
        if d < 1e-5:
            continue
        v.co -= back * float(d)
        moved += 1
        most = max(most, float(d))
    gbm.normal_update()
    print('face relief: his left upper face %d vertices back to the mirrored right (most %.4f m, the eye %.4f)'
          % (moved, most, d_eye))


def img_points(bm):
    """vert -> its point in head_input.png (px)."""
    p = bm.loops.layers.uv['proj']
    return {l.vert: (l[p].uv.x * 1024, (1 - l[p].uv.y) * 1024) for f in bm.faces for l in f.loops}


face_relief()
IMG = img_points(gbm)


def img_kd(bm, img):
    vs = [v for v in bm.verts if v.normal.dot(FWD) > 0.3]
    kd = KDTree(len(vs))
    for i, v in enumerate(vs):
        kd.insert((*img[v], 0), i)
    kd.balance()
    return lambda p: vs[kd.find((p[0], p[1], 0))[1]]


at_img = img_kd(gbm, IMG)


def lip_s(v, img):
    """Signed px below the lip line, None outside the mouth (or not facing forward)."""
    if v.normal.dot(FWD) <= 0.3:
        return None
    x, y = img[v]
    ly = interp(MOUTH_LINE, x)
    return None if ly is None else y - ly


def face_plane():
    """The face's midplane: through the eyes' midpoint, square to the level line between them. Returns (point, normal
    towards his left) and the nose tip."""
    el = at_img(head_shape.IMG_LANDMARKS['eye_l']).co
    er = at_img(head_shape.IMG_LANDMARKS['eye_r']).co
    nose = at_img(head_shape.IMG_LANDMARKS['nose']).co
    N = Vector((el.x - er.x, el.y - er.y, 0.0)).normalized()  # level: the eyes' depth from the generation is rough
    return (el + er) / 2, N, nose.copy()


SYM_M, SYM_N, NOSE = face_plane()


def mirror(p):
    return p - SYM_N * (2 * (p - SYM_M).dot(SYM_N))


# ---------------------------------------------------------------- 2. colour of the sources
def pixels(img):
    w, hh = img.size
    px = np.empty(w * hh * 4, np.float32); img.pixels.foreach_get(px)
    return px.reshape(hh, w, 4)


def raster(res, vals):
    """Per texel of the generated texture: vals (per face, per-corner value vectors) interpolated."""
    uvl = gbm.loops.layers.uv['UVMap']
    C = len(vals[0][0])
    acc = np.zeros((res, res, C), np.float32); hit = np.zeros((res, res), bool)
    for f, fv in zip(gbm.faces, vals):
        if f.material_index == 1:  # the cap: no texture
            continue
        P = np.array([tuple(l[uvl].uv) for l in f.loops]) * res
        A, B, Cc = P
        d = (B[0] - A[0]) * (Cc[1] - A[1]) - (Cc[0] - A[0]) * (B[1] - A[1])
        if abs(d) < 1e-9:
            continue
        x0, y0 = np.floor(P.min(0) - 1).astype(int).clip(0, res - 1)
        x1, y1 = np.ceil(P.max(0) + 1).astype(int).clip(0, res - 1)
        xs, ys = np.meshgrid(np.arange(x0, x1 + 1) + 0.5, np.arange(y0, y1 + 1) + 0.5)
        w0 = ((B[0] - xs) * (Cc[1] - ys) - (Cc[0] - xs) * (B[1] - ys)) / d
        w1 = ((Cc[0] - xs) * (A[1] - ys) - (A[0] - xs) * (Cc[1] - ys)) / d
        w2 = 1 - w0 - w1
        eps = 1.5 / max(1.0, np.abs(P - P.mean(0)).max())
        ins = (w0 > -eps) & (w1 > -eps) & (w2 > -eps)
        if not ins.any():
            continue
        V = np.array(fv, np.float32)
        val = w0[..., None] * V[0] + w1[..., None] * V[1] + w2[..., None] * V[2]
        yy, xx = ys[ins].astype(int), xs[ins].astype(int)
        acc[yy, xx] = val[ins]; hit[yy, xx] = True
    for _ in range(4):  # grow into the gutters
        for dy, dx in ((0, 1), (0, -1), (1, 0), (-1, 0)):
            sh = np.roll(np.roll(hit, dy, 0), dx, 1) & ~hit
            acc[sh] = np.roll(np.roll(acc, dy, 0), dx, 1)[sh]
            hit = hit | sh
    return acc, hit


def portrait_at(ppx, ix, iy):
    """head_input.png bilinearly at (ix, iy) px, and where it may be used: the head (alpha), not its uniform collar."""
    hh, ww = ppx.shape[:2]
    x = np.clip(ix - 0.5, 0, ww - 1.001); y = np.clip(hh - 0.5 - iy, 0, hh - 1.001)  # Blender rows run bottom-up
    x0, y0 = x.astype(int), y.astype(int); fx, fy = (x - x0)[..., None], (y - y0)[..., None]
    c = (ppx[y0, x0] * (1 - fx) * (1 - fy) + ppx[y0, x0 + 1] * fx * (1 - fy) +
         ppx[y0 + 1, x0] * (1 - fx) * fy + ppx[y0 + 1, x0 + 1] * fx * fy)
    rgb = c[..., :3]
    mx, mn = rgb.max(-1), rgb.min(-1)
    s = (mx - mn) / np.maximum(mx, 1e-4)
    r, g, b = rgb[..., 0], rgb[..., 1], rgb[..., 2]
    dm = np.maximum(mx - mn, 1e-4)
    hue = np.where(mx == r, (g - b) / dm % 6, np.where(mx == g, (b - r) / dm + 2, (r - g) / dm + 4)) * 60
    collar = (((hue < 12) | (hue > 340)) & (s > 0.6)) | ((hue > 180) & (hue < 300)) | ((s < 0.12) & (mx > 0.7))
    collar &= iy > PORTRAIT_COLLAR_Y
    w = np.clip((c[..., 3] - 0.5) * 4, 0, 1) * blur((~collar).astype(np.float32), 4)
    return rgb, w


def delight_portrait(ppx):
    """The portrait's own light taken out of its skin: the shadowed side of the face, the dark under the eyes and round
    the nose (the game lights the model itself). Per pixel the light is the skin's brightness averaged over
    PORTRAIT_LIGHT_R px (skin only - brows, eyes, lips and hair do not count); the skin is brought to one brightness,
    features keep their contrast to the skin round them. Hair is corrected as much as it is near the skin."""
    rgb = ppx[..., :3]
    hh = ppx.shape[0]
    iy = (hh - 1 - np.arange(hh))[:, None]  # px from the top (Blender rows run bottom-up)
    L = rgb @ LUM
    mx, mn = rgb.max(-1), rgb.min(-1)
    s = (mx - mn) / np.maximum(mx, 1e-4)
    skin = ((ppx[..., 3] > 0.5) & (rgb[..., 0] > rgb[..., 1]) & (rgb[..., 1] > rgb[..., 2]) & (mx > 0.5)
            & (s > 0.15) & (s < 0.7) & (iy < PORTRAIT_COLLAR_Y)).astype(np.float32)
    r = PORTRAIT_LIGHT_R
    wsum = blur(blur(skin, r), r)
    light = blur(blur(L * skin, r), r) / np.maximum(wsum, 1e-4)
    target = float(np.percentile(L[skin > 0], PORTRAIT_LIGHT_TARGET))
    gain = np.clip(target / np.maximum(light, 1e-3), *PORTRAIT_LIGHT_CLAMP)
    near = np.clip(wsum * 3, 0, 1)  # how much skin is round the pixel
    gain = 1 + (gain - 1) * near
    out = ppx.copy()
    lit = rgb * gain[..., None]
    # the shadows are also redder (under the eyes, round the nose): on the skin its hue is evened out towards the
    # skin's average round it, PORTRAIT_CHROMA_KEEP of the local variation stays
    chroma = lit / np.maximum(lit @ LUM, 1e-4)[..., None]
    mean = np.stack([blur(blur(chroma[..., i] * skin, r), r) for i in range(3)], -1) / np.maximum(wsum, 1e-4)[..., None]
    even = (mean + (chroma - mean) * PORTRAIT_CHROMA_KEEP) * (lit @ LUM)[..., None]
    k = (skin * near)[..., None]
    out[..., :3] = clean_lids(clean_under_eyes(np.clip(lit * (1 - k) + even * k, 0, 1)))
    print('portrait light: skin to %.2f, gain %.2f..%.2f' % (target, gain[skin > 0].min(), gain[skin > 0].max()))
    return out


def clean_under_eyes(rgb):
    """The bags and the dark under the eyes (the portrait's painted fatigue, darker on his right) taken out: a band
    under each lower rim (UNDER_EYE px below it, the ends faded) brought to the colour of the cheek under it, its fine
    texture kept (brightness relative to its own 5 px mean)."""
    hh, ww = rgb.shape[:2]
    ys = (hh - 1 - np.arange(hh))[:, None].astype(np.float32)  # px from the top (Blender rows run bottom-up)
    xs = np.arange(ww)[None, :].astype(np.float32)
    L = rgb @ LUM
    detail = np.clip(L / np.maximum(blur(L, 5), 1e-4), 0.85, 1.15)[..., None]
    (t0, t1), (b0, b1) = UNDER_EYE
    for s, rims in EYE_RIMS.items():
        lo = rims['lower']
        x0, x1 = lo[0][0], lo[-1][0]
        d = ys - np.interp(xs, [x for x, _ in lo], [y for _, y in lo])
        wx = np_smooth(xs, x0 - 14, x0 + 4) * (1 - np_smooth(xs, x1 - 4, x1 + 14))
        wgt = (np_smooth(d, t0, t1) * (1 - np_smooth(d, b0, b1)) * wx)[..., None]
        band = np.broadcast_to((d > b1) & (d < b1 + 25) & (wx > 0.5), L.shape)
        cheek = np.median(rgb[band], 0)
        rgb = rgb * (1 - wgt * UNDER_EYE_AMOUNT) + np.clip(cheek * detail, 0, 1) * wgt * UNDER_EYE_AMOUNT
        print('under eye %s: cheek %s' % (s, np.round(cheek, 2)))
    return rgb


def clean_lids(rgb):
    """The portrait's light on the upper lids taken out: over each upper rim (LID_BAND px, the ends faded) the pixels
    brighter than the lid's own median brought down to it, its colour kept; nothing darker than the lid. (The lit lid
    and the highlight under his left brow, round in our light, read as a puffed-up lid.)"""
    hh, ww = rgb.shape[:2]
    ys = (hh - 1 - np.arange(hh))[:, None].astype(np.float32)  # px from the top (Blender rows run bottom-up)
    xs = np.arange(ww)[None, :].astype(np.float32)
    t0, t1 = LID_BAND
    for s, rims in EYE_RIMS.items():
        up = rims['upper']
        x0, x1 = up[0][0], up[-1][0]
        d = np.interp(xs, [x for x, _ in up], [y for _, y in up]) - ys  # px over the rim
        wx = np_smooth(xs, x0 - 6, x0 + 6) * (1 - np_smooth(xs, x1 - 6, x1 + 6))
        wgt = np_smooth(d, t0 - 1, t0 + 2) * (1 - np_smooth(d, t1 - 4, t1 + 2)) * wx
        L = rgb @ LUM
        band = (wgt > 0.5)
        ref = float(np.median(L[band]))
        k = (wgt * np.clip(1 - ref / np.maximum(L, 1e-4), 0, 1))[..., None]  # how much over the lid's level
        rgb = rgb * (1 - k)
        print('upper lid %s: to %.2f (%d px brighter)' % (s, ref, int((band & (L > ref)).sum())))
    return rgb


def portrait_hair(ppx):
    """Median colour of the hair in head_input.png: dark brown pixels of the head above the eyes."""
    top = min(min(y for _, y in r['upper']) for r in EYE_RIMS.values())
    a = ppx[::-1][:int(top) - 20]  # rows from the top of the picture
    a = a[a[..., 3] > 0.5][:, :3]
    v = a.max(1)
    hue_ok = (a[:, 0] > a[:, 1]) & (a[:, 1] > a[:, 2])
    return np.median(a[(v < 0.55) & (v > 0.08) & hue_ok], 0)


def source_texture():
    """The generated head's texture redone: at the front the portrait itself (it is the front view, exact); elsewhere
    the generated texture with the portrait's skin and hair colours (keeping CHROMA_KEEP / HAIR_KEEP of its own
    variation) and the light baked into it taken out (per vertex the texture's brightness, smoothed over the mesh, is
    the light that fell there). Skin or hair: the faces' classes smoothed over the mesh; the back of the head above the
    nape is all hair (the generation leaves pink patches there). Returns the image and the skin colour (sRGB)."""
    portrait = bpy.data.images.load(PORTRAIT, check_existing=True)
    gpx, ppx = pixels(gimg), delight_portrait(pixels(portrait))
    res = gimg.size[0]
    uvl = gbm.loops.layers.uv['UVMap']
    g, p = [], []
    for f in gbm.faces:
        if is_skin(f) and f.normal.dot(FWD) > 0.85 and f.calc_center_median().z > CHIN_Z:
            q = f.loops[0][puv].uv
            pc = ppx[min(1023, int(q.y * 1024)), min(1023, int(q.x * 1024))]
            u = f.loops[0][uvl].uv
            if pc[3] > 0.5:
                g.append(gpx[min(res - 1, int(u.y * res)), min(res - 1, int(u.x * res)), :3]); p.append(pc[:3])
    g, p = np.median(np.array(g), 0), np.median(np.array(p), 0)
    ph = portrait_hair(ppx)
    rgb = gpx[..., :3].copy()
    L = rgb @ LUM
    gbm.verts.index_update()
    n = len(gbm.verts)
    nb = [[e.other_vert(v).index for e in v.link_edges] for v in gbm.verts]
    hv = np.array([np.mean([is_hair(f) for f in v.link_faces]) if v.link_faces else 0.0 for v in gbm.verts])
    eye_z = (at_img(EYE_RIMS['l']['upper'][2]).co.z + at_img(EYE_RIMS['r']['upper'][3]).co.z) / 2
    back = np.array([float((v.normal.dot(FWD) < -0.1 and v.co.z > CHIN_Z + 0.03) or
                           (v.normal.dot(FWD) < 0.2 and v.co.z > eye_z + 0.03)) for v in gbm.verts])
    hv = np.maximum(hv, back)
    lv, cnt = np.zeros(n), np.zeros(n)
    for f in gbm.faces:
        if f.material_index == 1:
            continue
        for l in f.loops:
            u = l[uvl].uv
            lv[l.vert.index] += L[min(res - 1, int(u.y * res)), min(res - 1, int(u.x * res))]; cnt[l.vert.index] += 1
    lv /= np.maximum(cnt, 1)

    def smooth(a, it, w=None):
        w = np.ones(n) if w is None else w
        a = a.copy()
        for _ in range(it):
            num = np.array([a[i] * w[i] + sum(a[j] * w[j] for j in nb[i]) for i in range(n)])
            den = np.array([w[i] + sum(w[j] for j in nb[i]) for i in range(n)])
            a = np.where(den > 1e-6, num / np.maximum(den, 1e-6), a)
        return a

    hv = smooth(hv, 4)
    hard = np.clip((hv - 0.3) / 0.4, 0, 1)
    l_skin = smooth(lv, DELIGHT_IT, 1 - hard + 1e-3)
    l_hair = smooth(lv, DELIGHT_IT, hard + 1e-3)
    skin_l0, hair_l0 = float(np.median(lv[hard < 0.1])), float(np.median(lv[hard > 0.9]))
    f_skin = np.clip(skin_l0 / np.maximum(l_skin, 1e-3), *DELIGHT_CLAMP)
    f_hair = np.clip(1 + (hair_l0 / np.maximum(l_hair, 1e-3) - 1) * DELIGHT_HAIR, *DELIGHT_CLAMP)
    vals = []
    for f in gbm.faces:
        vals.append([(l[puv].uv.x * 1024, (1 - l[puv].uv.y) * 1024, l[FACING].uv.x, hard[l.vert.index],
                      f_skin[l.vert.index], f_hair[l.vert.index], float(f[EAR]))
                     for l in f.loops])
    acc, hit = raster(res, vals)
    hair_w = acc[..., 3:4]
    chroma = rgb / np.maximum(L, 1e-4)[..., None]

    def towards(ref_g, ref_p, keep):
        lg, lp = max(float(ref_g @ LUM), 1e-4), max(float(ref_p @ LUM), 1e-4)
        return np.clip((ref_p / lp + (chroma - ref_g / lg) * keep) * (L * lp / lg)[..., None], 0, 1)

    skin_rgb = np.clip(towards(g, p, CHROMA_KEEP) * acc[..., 4:5], 0, 1)
    hg = np.median(rgb[(hair_w[..., 0] > 0.99) & hit], 0)
    hair_rgb = towards(hg, ph, HAIR_KEEP) * acc[..., 5:6]
    hl = hair_rgb @ LUM
    hair_rgb = np.clip(hair_rgb * (np.minimum(hl, float(ph @ LUM) * HAIR_MAX_L) / np.maximum(hl, 1e-4))[..., None], 0, 1)
    out = skin_rgb * (1 - hair_w) + hair_rgb * hair_w
    pp, pw = portrait_at(ppx, acc[..., 0], acc[..., 1])
    w = (np.clip((acc[..., 2] - PORTRAIT_FRONT[0]) / (PORTRAIT_FRONT[1] - PORTRAIT_FRONT[0]), 0, 1) * pw)[..., None]
    w = w * w * (3 - 2 * w)
    out = np.where(hit[..., None], out * (1 - w) + pp * w, rgb)
    # (the ears get one skin colour on the head itself: ear_surroundings - painted here, it spread over the hair)
    img = bpy.data.images.new('head_src', res, res)
    img.colorspace_settings.name = 'sRGB'
    img.pixels.foreach_set(np.concatenate([out, np.ones_like(out[..., :1])], axis=2).astype(np.float32).ravel())
    img.pack()
    print('colour: generated skin %s portrait %s, hair %s portrait %s; delight x%.2f..%.2f' % (
        np.round(g, 2), np.round(p, 2), np.round(hg, 2), np.round(ph, 2), f_skin.min(), f_skin.max()))
    return img, p


SRC_IMG, SKIN_SRGB = source_texture()
SKIN_LIN = to_linear(SKIN_SRGB)


RIM_PTS = []  # the cut's rim (rim_colours)


def rim_colours():
    """Colour of the cut's rim (the beard's ends, the skin under the chin): for the cap and the neck, which had a flat
    skin colour and showed as pale patches under the beard. Returns co -> linear RGB (the nearest rim points')."""
    src = pixels(SRC_IMG)
    res = SRC_IMG.size[0]
    uvl = gbm.loops.layers.uv['UVMap']
    rim = {}
    for f in gbm.faces:
        if f.material_index == 1:
            continue
        for l in f.loops:
            if any(g.material_index == 1 for g in l.vert.link_faces):
                u = l[uvl].uv
                c = src[min(res - 1, int(u.y * res)), min(res - 1, int(u.x * res)), :3]
                if c.max() - c.min() > 0.12 * c.max():  # not the generated shirt collar's white
                    rim.setdefault(l.vert, []).append(c)
    pts = [(v.co.copy(), np.array(to_linear(np.mean(c, 0)))) for v, c in rim.items()]
    RIM_PTS[:] = [p for p, _ in pts]
    kd = KDTree(len(pts))
    for i, (p, _) in enumerate(pts):
        kd.insert(p, i)
    kd.balance()

    def at(co, k=6):
        near = kd.find_n(co, k)
        w = np.array([1 / (d + 1e-3) for _, _, d in near])
        return (np.array([pts[i][1] for _, i, _ in near]) * w[:, None]).sum(0) / w.sum(), near[0][2]
    return at


RIM_AT = rim_colours()
for v in gbm.verts:
    v[COL] = (*RIM_AT(v.co)[0], 1.0)


# ---------------------------------------------------------------- eyes and mouth, measured on the generated head
EYE = {}
for s, rims in EYE_RIMS.items():
    up, lo = rims['upper'], rims['lower']
    xs = [q[0] for q in up]
    x0, x1 = min(xs), max(xs)
    opens = [(x, interp(lo, x) - interp(up, x)) for x in range(int(x0), int(x1) + 1)]
    xc, omax = max(opens, key=lambda t: t[1])
    U3, L3 = at_img((xc, interp(up, xc))).co, at_img((xc, interp(lo, xc))).co
    pivot = (U3 + L3) / 2 - FWD * EYE_DEPTH
    ang = lambda q: math.atan2((q - pivot).z, (q - pivot).dot(FWD))  # noqa: E731
    EYE[s] = dict(x0=x0, x1=x1, omax=omax, pivot=pivot, deg=math.degrees(ang(U3) - ang(L3)), U3=U3.copy(), L3=L3.copy())
BLINK_DEG = max(e['deg'] for e in EYE.values())
print('eyes: blink %.1f deg (l %.1f, r %.1f)' % (BLINK_DEG, EYE['l']['deg'], EYE['r']['deg']))
MOUTH_C = sum((at_img(q).co for q in MOUTH_LINE), Vector()) / len(MOUTH_LINE)

# ---------------------------------------------------------------- the sources as objects
body = set(members('body'))
src_head = new_object('_SrcHead', gbm, [material('_SrcHead', SRC_IMG, 0.55), material('_SrcSkin', None, 0.55, SKIN_LIN, 'col')],
                      part=False)
GEN_BVH = BVHTree.FromBMesh(gbm)
GEN_FACES = [(f[CLS], [l[puv].uv.copy() for l in f.loops], [v.co.copy() for v in f.verts]) for f in gbm.faces]
gbm.free()


def neck_source():
    """The neck: a plain smooth tube from inside the tunic's collar (NECK_Z0) up into the head (NECK_INTO above the
    cut), no anatomy - MPFB's neck, squeezed into the collar, made bumps where it ran into the jaw. Straight up the
    collar's axis, its rings the collar's ellipse (head_shape.NECK_*), only the top ones kept inside the cut's outline
    less NECK_INSET (measured round the same axis: round the cut's own middle, far forward under the jaw, the tube
    leant forward and its back was cut away - a thin crooked neck with a gap behind it in the collar); ends capped."""
    ax = sc['uniform']['NECK_AXIS']
    c0 = Vector((ax[0], ax[1] + head_shape.NECK_C_DY, NECK_Z0))
    cut = CHIN_Z - NECK_CUT
    n = NECK_SEGS
    rim_r = [0.0] * n
    for p in RIM_PTS:  # the cut's outline per direction round the collar's axis
        d = p.xy - c0.xy
        k = int((math.atan2(d.x, -d.y) % (2 * math.pi)) / (2 * math.pi) * n) % n
        rim_r[k] = max(rim_r[k], d.length)
    for _ in range(n):
        if not all(rim_r):
            rim_r = [r or max(rim_r[k - 1], rim_r[(k + 1) % n]) for k, r in enumerate(rim_r)]
    for _ in range(4):
        rim_r = [rim_r[k] * 0.5 + (rim_r[k - 1] + rim_r[(k + 1) % n]) * 0.25 for k in range(n)]
    # the collar's inside (the red halves, the dark stand between them, the shirt's collar inside them) per direction:
    # its narrowest and its top
    cb = bmesh.new()
    for nm in ('Collar', 'CollarStand', 'ShirtCollar'):
        o = bpy.data.objects.get(nm)
        if o is not None:
            me_ = o.data.copy(); me_.transform(o.matrix_world); cb.from_mesh(me_); bpy.data.meshes.remove(me_)
    coll = BVHTree.FromBMesh(cb); cb.free()
    coll_r, coll_top = [0.0] * n, [0.0] * n
    for k in range(n):
        a = 2 * math.pi * (k + 0.5) / n
        d = Vector((math.sin(a), -math.cos(a), 0.0))
        hits = [(z, coll.ray_cast(Vector((c0.x, c0.y, z)), d, 0.2)[0]) for z in np.arange(1.72, 1.861, 0.002)]
        hits = [(z, (q.xy - c0.xy).length) for z, q in hits if q is not None]
        if hits:
            coll_top[k] = hits[-1][0]
            coll_r[k] = min(r for z, r in hits if z > coll_top[k] - 0.05)
    for _ in range(3):
        coll_r = [coll_r[k] * 0.5 + (coll_r[k - 1] + coll_r[(k + 1) % n]) * 0.25 for k in range(n)]
    print('neck: the collar inside %.3f..%.3f, its top %.3f..%.3f' % (min(coll_r), max(coll_r), min(coll_top),
                                                                        max(coll_top)))
    b = bmesh.new()
    rings = []
    for i in range(NECK_RINGS + 1):
        t = i / NECK_RINGS
        z = NECK_Z0 + (cut + NECK_INTO - NECK_Z0) * t
        w = smoothstep(z, cut - 0.01, cut)  # the collar's ellipse, at the top inside the cut's outline
        c = c0.xy
        ring = []
        for k in range(n):
            a = 2 * math.pi * (k + 0.5) / n
            d = Vector((math.sin(a), -math.cos(a)))
            # the collar's ellipse all the way up (inside the jaw's cut): wider, it shows over the collar
            r = head_shape.neck_radius(d.x, d.y) * NECK_FIT
            inside = 1 - smoothstep(z, coll_top[k] - NECK_COLLAR_EASE[0], coll_top[k] + NECK_COLLAR_EASE[1])
            fill = max(inside * (1 - smoothstep(-d.y, 0.2, 0.6)), 1 - inside)
            rf = coll_r[k] - NECK_COLLAR_GAP
            r = min(r + (rf - r) * fill, rf)  # never out of the shirt collar (wider than it, over the collar's top the
            # neck stood out over the shirt and hid its white edge but at the front: the portrait's runs all along)
            # kept inside the cut's outline, not widened to it: widened, its top came out of the jaw's underside (which
            # narrows over the cut, and at the sides lies 1-2 cm over it) as a thin flange round the neck. It runs up
            # into the head and the corner is rounded (FILLET)
            r = r + (min(r, rim_r[k] - NECK_INSET) - r) * w
            ring.append(b.verts.new((c.x + d.x * r, c.y + d.y * r, z)))
        rings.append(ring)
    for r0, r1 in zip(rings, rings[1:]):
        for k in range(n):
            b.faces.new((r0[k], r0[(k + 1) % n], r1[(k + 1) % n], r1[k]))
    b.faces.new(rings[0][::-1]); b.faces.new(rings[-1])
    bmesh.ops.recalc_face_normals(b, faces=b.faces[:])
    col = b.verts.layers.float_color.new('col')
    for v in b.verts:  # the beard's colour carried down under the jaw, skin further from it
        c, d = RIM_AT(v.co)
        w = smoothstep(d, 0.003, 0.012)  # (further down, the rim's colours ran down the neck in stripes)
        shade = NECK_SHADE[1] + (NECK_SHADE[0] - NECK_SHADE[1]) * smoothstep(v.co.z, cut - 0.005, NECK_Z0 + 0.02)
        v[col] = (*((c * (1 - w) + np.array(SKIN_LIN) * w) * shade), 1.0)
    ob = new_object('_SrcNeck', b, [material('_SrcSkin', None, 0.55, SKIN_LIN, 'col')], part=False)
    b.free()
    return ob


src_neck = neck_source()


# ---------------------------------------------------------------- 3. one closed head: remesh, smooth, decimate, unwrap
def under_jaw(b):
    """The neck's column on the decimated head made anew: the remeshed tube cut off UNDER_JOIN under the cut (under the
    corner into the jaw) and from that rim straight down to NECK_Z0 in even rings on the tube's surface (src_neck),
    capped - one column of quads per rim vertex. (Remeshed and decimated, the neck was long slivers from the collar
    to the jaw - bright streaks down it.)"""
    cut = CHIN_Z - NECK_CUT
    top_z = cut - UNDER_JOIN
    ax = sc['uniform']['NECK_AXIS']
    c0 = Vector((ax[0], ax[1] + head_shape.NECK_C_DY, 0.0))
    tube = BVHTree.FromObject(src_neck, bpy.context.evaluated_depsgraph_get())

    def on_tube(a, z):
        o = Vector((c0.x, c0.y, z)); d = Vector((math.cos(a), math.sin(a), 0.0))
        hit = tube.ray_cast(o, d, 0.3)[0]
        return hit if hit is not None else o + d * 0.05
    bmesh.ops.bisect_plane(b, geom=b.verts[:] + b.edges[:] + b.faces[:], dist=1e-6, plane_co=(0, 0, top_z),
                           plane_no=(0, 0, 1), clear_inner=True)
    bmesh.ops.delete(b, geom=[v for v in b.verts if not v.link_faces], context='VERTS')
    edges = {e for e in b.edges if e.is_boundary}
    loops = []
    while edges:
        e = edges.pop()
        loop = [e.verts[0], e.verts[1]]
        while True:
            nxt = [f for f in loop[-1].link_edges if f in edges]
            if not nxt:
                break
            edges.discard(nxt[0])
            v = nxt[0].other_vert(loop[-1])
            if v is loop[0]:
                break
            loop.append(v)
        loops.append(loop)
    loops.sort(key=lambda l: -len(l))
    rim = loops[0]
    for small in loops[1:]:
        bmesh.ops.holes_fill(b, edges=list({e for v in small for e in v.link_edges if e.is_boundary}), sides=0)
    ang = [math.atan2(v.co.y - c0.y, v.co.x - c0.x) for v in rim]
    rings_z = list(np.arange(top_z, NECK_Z0, -UNDER_STEP)) + [NECK_Z0]
    cols = []
    for v, a in zip(rim, ang):
        r0 = (v.co.xy - c0.xy).length
        k0 = r0 / max((on_tube(a, top_z).xy - c0.xy).length, 1e-6)  # the rim off the tube (smoothed in): eased out
        col = [v]
        for j, z in enumerate(rings_z[1:], 1):
            q = on_tube(a, z)
            k = 1 + (k0 - 1) * max(0.0, 1 - j / 3)
            col.append(b.verts.new((c0.x + (q.x - c0.x) * k, c0.y + (q.y - c0.y) * k, z)))
        cols.append(col)
    n = len(cols)
    for i in range(n):
        c1, c2 = cols[i], cols[(i + 1) % n]
        for j in range(len(c1) - 1):
            b.faces.new((c1[j], c2[j], c2[j + 1], c1[j + 1]))
    centre = b.verts.new((c0.x, c0.y, NECK_Z0))
    for i in range(n):
        b.faces.new((cols[i][-1], cols[(i + 1) % n][-1], centre))
    bmesh.ops.triangulate(b, faces=[f for f in b.faces if len(f.verts) > 3])
    bmesh.ops.recalc_face_normals(b, faces=b.faces[:])
    print('neck column: rim of %d vertices (rims %s), %d rings' % (n, [len(l) for l in loops], len(rings_z)))


def smooth_throat(b):
    """The throat between the collar's front and the chin smoothed (THROAT_SMOOTH): Taubin rounds (no shrinking), the
    weight fading in over a centimetre at either end; at the back only up to the cut (the hair's edge stays)."""
    cut = CHIN_Z - NECK_CUT
    ax = sc['uniform']['NECK_AXIS']
    cy = ax[1] + head_shape.NECK_C_DY
    b.verts.index_update()
    co = np.array([v.co[:] for v in b.verts])
    ed = np.array([[e.verts[0].index, e.verts[1].index] for e in b.edges])
    deg = np.bincount(ed.ravel(), minlength=len(co)).astype(float)
    lo = cut - THROAT_SMOOTH[0]
    w = np.zeros(len(co))
    for i, (x, y, z) in enumerate(co):
        d = math.hypot(x - ax[0], y - cy) or 1e-9
        front = smoothstep(-(y - cy) / d, -0.2, 0.3)
        top = cut - 0.004 + (CHIN_Z - THROAT_SMOOTH[1] - cut + 0.004) * front
        w[i] = smoothstep(z, lo, lo + 0.01) * (1 - smoothstep(z, top - 0.008, top))
    for _ in range(THROAT_SMOOTH[2]):
        for f in (0.5, -0.53):
            s_ = np.zeros_like(co)
            np.add.at(s_, ed[:, 0], co[ed[:, 1]]); np.add.at(s_, ed[:, 1], co[ed[:, 0]])
            co = co + (s_ / np.maximum(deg, 1)[:, None] - co) * (f * w)[:, None]
    for v, c in zip(b.verts, co):
        v.co = c
    print('throat: %d vertices smoothed' % int((w > 0.5).sum()))


def build_head():
    b = bmesh.new()
    for o in (src_head, src_neck):
        b.from_mesh(o.data)
    me = bpy.data.meshes.new('Head'); b.to_mesh(me); b.free()
    ob = bpy.data.objects.new('Head', me); sc.collection.objects.link(ob)
    ob['head_part'] = True
    me.remesh_voxel_size = VOXEL
    bpy.context.view_layer.objects.active = ob
    for o in sc.objects:
        o.select_set(o == ob)
    bpy.ops.object.voxel_remesh()
    n_remesh = len(ob.data.polygons)
    # the ragged beard bottom and the neck's join (nothing else: smoothed, the curls, moustache and lips melted). Taubin
    # smoothing (a shrink and an inflate step per round) keeps the volume; per vertex weight 0..1.
    me = ob.data
    co = np.array([v.co[:] for v in me.vertices])
    ed = np.array([e.vertices[:] for e in me.edges])
    nv = len(co)
    deg = np.bincount(ed.ravel(), minlength=nv).astype(float)
    cut = CHIN_Z - NECK_CUT
    band = np.array([smoothstep(z, cut + BEARD_SMOOTH[0], cut) * smoothstep(z, HEAD_Z + 0.01, HEAD_Z + 0.03)
                     for z in co[:, 2]])
    # ... and the jaw's underside back to the ears (facing down, under the mouth): seen from below it was a crumpled
    # sheet with white glints on its folds
    nz = np.array([v.normal.z for v in me.vertices])
    down = np.array([smoothstep(-n, UNDER_SMOOTH[0], UNDER_SMOOTH[1]) * smoothstep(z, CHIN_Z + UNDER_SMOOTH[2],
                                                                                   CHIN_Z + UNDER_SMOOTH[3])
                     for n, z in zip(nz, co[:, 2])])
    band = np.maximum(band, down)

    def taubin(w, rounds):
        nonlocal co
        for _ in range(rounds):
            for f in (0.5, -0.53):
                s_ = np.zeros_like(co)
                np.add.at(s_, ed[:, 0], co[ed[:, 1]]); np.add.at(s_, ed[:, 1], co[ed[:, 0]])
                avg = s_ / np.maximum(deg, 1)[:, None]
                co = co + (avg - co) * (f * w)[:, None]
    taubin(band, BEARD_SMOOTH[1])
    # the corner where the head's cut floor meets the neck rounded off into a slope (plain Laplacian: it fills a hollow
    # corner): seen from below in the collar's opening it was a flat shelf under the jaw with a crease and a pale rim
    fillet = np.array([smoothstep(z, cut - FILLET[0], cut - FILLET[0] * 0.4) * smoothstep(z, cut + FILLET[1], cut)
                       for z in co[:, 2]])
    for _ in range(FILLET[2]):
        s_ = np.zeros_like(co)
        np.add.at(s_, ed[:, 0], co[ed[:, 1]]); np.add.at(s_, ed[:, 1], co[ed[:, 0]])
        co = co + (s_ / np.maximum(deg, 1)[:, None] - co) * (0.5 * fillet)[:, None]
    me.vertices.foreach_set('co', co.astype(np.float32).ravel())
    me.update()
    dec = ob.modifiers.new('D', 'DECIMATE')
    dec.ratio = TRIS / (2 * len(ob.data.polygons))  # remesh quads -> two triangles each
    bpy.ops.object.modifier_apply(modifier='D')
    b = bmesh.new(); b.from_mesh(ob.data)
    bmesh.ops.triangulate(b, faces=b.faces[:])
    # round the eye openings the faces split twice: the eyeball shows inside the rim, and the rim follows the edges
    opening = [e['pivot'] + FWD * EYE_DEPTH for e in EYE.values()]
    for _ in range(2):
        near = {ed for f in b.faces if min((f.calc_center_median() - o).length for o in opening) < EYE_SUBDIV_R
                for ed in f.edges}
        bmesh.ops.subdivide_edges(b, edges=list(near), cuts=1, use_grid_fill=True)
        bmesh.ops.triangulate(b, faces=b.faces[:])
    # folds the decimation left: two triangles on the same three vertices, back to back (a fin - an edge of four
    # faces, non-manifold for the game's importer): both out, the hole (if any) closed
    seen = {}
    for f in b.faces:
        seen.setdefault(frozenset(v.index for v in f.verts), []).append(f)
    fins = [f for fs in seen.values() if len(fs) > 1 for f in fs]
    if fins:
        bmesh.ops.delete(b, geom=fins, context='FACES')
        bmesh.ops.delete(b, geom=[v for v in b.verts if not v.link_faces], context='VERTS')
        holes = [e for e in b.edges if e.is_boundary]
        if holes:
            bmesh.ops.holes_fill(b, edges=holes, sides=8)
            bmesh.ops.triangulate(b, faces=b.faces[:])
        print('head: %d folded faces removed, %d edges of holes closed' % (len(fins), len(holes)))
    under_jaw(b)
    smooth_throat(b)
    b.to_mesh(ob.data); b.free()
    for p in ob.data.polygons:
        p.use_smooth = True
    print('head: remesh %d quads -> %d tris' % (n_remesh, len(ob.data.polygons)))
    # UVs: smart projection, islands packed
    bpy.ops.object.mode_set(mode='EDIT')
    bpy.ops.mesh.select_all(action='SELECT')
    bpy.ops.uv.smart_project(angle_limit=math.radians(66), island_margin=0.004, area_weight=0.0)
    bpy.ops.uv.pack_islands(margin=0.004, rotate=True)
    bpy.ops.object.mode_set(mode='OBJECT')
    uvs = ob.data.uv_layers
    for l in [l for l in uvs if l != uvs.active]:  # the sources' layers, carried through the remesh
        uvs.remove(l)
    uvs.active.name = 'UVMap'
    return ob


head = build_head()


def _hull(pts):
    """Convex hull of 2D points (counter-clockwise)."""
    pts = sorted(map(tuple, pts))
    if len(pts) < 3:
        return pts
    cross = lambda o, a, b: (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])  # noqa: E731
    lo, up = [], []
    for q in pts:
        while len(lo) >= 2 and cross(lo[-2], lo[-1], q) <= 0:
            lo.pop()
        lo.append(q)
    for q in reversed(pts):
        while len(up) >= 2 and cross(up[-2], up[-1], q) <= 0:
            up.pop()
        up.append(q)
    return lo[:-1] + up[:-1]


def head_ears():
    """The ears on the head: inside EAR_AT's ellipsoids (measured on the generated head - MPFB's ears, which the
    generated ones were found by, sit ~3 cm off) and seen from the side within the outline of the flap - what stands
    out of the head (EAR_PROUD over the head smoothed EAR_SMOOTH rounds), its bowl too whichever way it faces; and
    whatever faces sideways in the ellipsoid's core (EAR_CORE of its radii: the bowl in front, which the rim's outline
    - it stands out at the back - left out with the generation's dark shade and red streaks in it). (The whole
    ellipsoid took in the hair round the ear: a ring of skin colour ~1 cm wide on the hair.) Returns their points and
    each ear's middle."""
    me = head.data
    co = np.array([v.co[:] for v in me.vertices]); nrm = np.array([v.normal[:] for v in me.vertices])
    ed = np.array([e.vertices[:] for e in me.edges])
    deg = np.maximum(np.bincount(ed.ravel(), minlength=len(co)), 1)[:, None]
    sm = co.copy()
    for _ in range(EAR_SMOOTH):
        acc = np.zeros_like(sm)
        np.add.at(acc, ed[:, 0], sm[ed[:, 1]]); np.add.at(acc, ed[:, 1], sm[ed[:, 0]])
        sm = sm + (acc / deg - sm) * 0.5
    proud = ((co - sm) * nrm).sum(1)
    pts = []
    for c, r in EAR_AT:
        inside = (((co - np.array(c)) / np.array(r)) ** 2).sum(1) < 1
        side = inside & (np.abs(nrm[:, 0]) > 0.2)
        flap = side & (proud > EAR_PROUD)
        hull = _hull(co[flap][:, 1:3])
        ok = np.ones(len(co), bool)
        for a, b in zip(hull, hull[1:] + hull[:1]):  # inside the (counter-clockwise) outline: left of every edge
            ok &= (b[0] - a[0]) * (co[:, 2] - a[1]) - (b[1] - a[1]) * (co[:, 1] - a[0]) >= 0
        core = (((co - np.array(c)) / np.array(r)) ** 2).sum(1) < EAR_CORE ** 2
        sel = (inside & ok) | (core & side)
        pts += [Vector(q) for q in co[sel]]
        print('ear at %s: %d vertices of %d in the ellipsoid (%d standing out)' % (
            tuple(round(x, 3) for x in c), sel.sum(), side.sum(), flap.sum()))
    mids = [Vector(c) for c, _ in EAR_AT]
    return pts, mids


