def side_class():
    """His left's sideburn and the hair round it take his right's class where his right is hair (only skin made
    hair): generated, the left sideburn in front of the ear was skin colour with a dark stripe down it and pale
    blotches stood in the hair over the ear. Where the surface faces sideways, |x| over SIDE_CLASS[0], from over the
    mirrored jaw up to SIDE_CLASS[1]; neither ear nor its mirror image (they sit apart: his right 6 mm lower, 8 mm
    further forward)."""
    ear = KDTree(len(HEAD_EAR_PTS))
    for i, q in enumerate(HEAD_EAR_PTS):
        ear.insert(q, i)
    ear.balance()
    rv = [v for v in hb.verts if v.co.x < 0]
    kd = KDTree(len(rv))
    for i, v in enumerate(rv):
        kd.insert(v.co, i)
    kd.balance()
    n = 0
    for v in hb.verts:
        c = v.co
        if (c.x < SIDE_CLASS[0] or not CHIN_Z + MIRROR_JAW[1] < c.z < SIDE_CLASS[1] or v.normal.x < 0.25
                or HCLS[v] != head_shape.SKIN):
            continue
        m = Vector((-c.x, c.y, c.z))
        if ear.find(c)[2] < SIDE_CLASS[2] or ear.find(m)[2] < SIDE_CLASS[2]:
            continue
        q, k, d = kd.find(m)
        if d < 0.01 and HCLS[rv[k]] == head_shape.HAIR:
            HCLS[v] = head_shape.HAIR
            n += 1
    print('his left sideburn: %d vertices made hair as his right' % n)


side_class()


# The opening each eye takes: its own, as the picture painted it (the head is the generated one, not mirrored: an
# opening mirrored over from the other eye missed the right eye's own by up to 1.2 cm - the ball stood out of the lids
# and the lids round it were lifted 6 mm).
EYE_FROM = {'l': 'l', 'r': 'r'}
_EIMG = {}


def eye_img(v, s):
    """Where in head_input.png vertex v lies for eye s's outline: its own place, or its mirror image's for an eye
    that takes the other's opening."""
    if EYE_FROM[s] == s:
        return HIMG[v]
    if v not in _EIMG:
        q = from_generated(mirror(v.co))[1]
        _EIMG[v] = q if q is not None else (-1e4, -1e4)
    return _EIMG[v]


def lid_weight(v, s):
    """Upper lid weight for a blink of BLINK_DEG: rim to rim it grades so every point lands on the lower rim."""
    e, src = EYE[s], EYE[EYE_FROM[s]]
    if v.normal.dot(FWD) <= 0.3:
        return 0.0
    x, y = eye_img(v, s)
    up, lo = EYE_RIMS[EYE_FROM[s]]['upper'], EYE_RIMS[EYE_FROM[s]]['lower']
    if not src['x0'] <= x <= src['x1']:
        return 0.0
    yu, yl = interp(up, x), interp(lo, x)
    scale = e['deg'] / BLINK_DEG  # the narrower eye turns less
    if y > yl:
        return 0.0
    if y >= yu:
        return (yl - y) / src['omax'] * scale
    return (yl - yu) / src['omax'] * scale * (1 - smoothstep(yu - y, 0, LID_FADE))


def jaw_weight(v):
    """None: MPFB's jaw weight stays. 0: no jaw (above the lip line, the moustache). Else at least this much: the
    lower lip just under the line fully, fading out down to JAW_FULL px."""
    if HCLS[v] == head_shape.HAIR and v.co.z > MOUTH_C.z - 0.02 and v.normal.dot(FWD) > 0.3:
        return 0.0
    s = lip_s(v, HIMG)
    if s is None:
        return None
    return 0.0 if s <= 0.5 else 1 - smoothstep(s, JAW_FULL * 0.5, JAW_FULL)


def hair_detail():
    """Strands on the hair, whiskers and moustache (the generated texture is smoothed into a flat mass): per texel the
    hair's direction - away from the crown along the surface (down and back over the head, down the whiskers) - and
    across it streaks of a few widths (clumps, strands); into the albedo (lighter and darker strands) and a normal
    map (each strand a ridge)."""
    hair_v = np.array([1.0 if HCLS[v] == head_shape.HAIR else 0.0 for v in hb.verts])
    for _ in range(2):  # soft edge round the hairline
        nb = np.array([np.mean([hair_v[e.other_vert(v).index] for e in v.link_edges]) for v in hb.verts])
        hair_v = 0.5 * hair_v + 0.5 * nb
    me = head.data
    data, cov = mat_util.raster(me, TEX, hair_v[:, None])
    p, n, hw = data[..., :3], data[..., 3:6], data[..., 6]
    n = n / np.maximum(np.linalg.norm(n, axis=-1, keepdims=True), 1e-6)
    cx = float(np.mean([v.co.x for v in hb.verts]))
    # combed from the crown down: strands run along the meridians round a vertical axis through the crown, so across
    # them the coordinate is the angle round it (times a typical radius), waving a little down their length
    phi = np.arctan2(p[..., 0] - cx, p[..., 1] - HAIR_CROWN[0])
    a = HAIR_CROWN[1] - p[..., 2]
    c = phi * 0.09 + 0.003 * np.sin(a * 70.0)
    rng = np.random.default_rng(7)
    s = np.zeros_like(c)
    for freq, amp in HAIR_STREAKS:
        ph = rng.uniform(0, 2 * np.pi)
        s += amp * np.sin(2 * np.pi * c * freq + ph + 1.5 * np.sin(2 * np.pi * a * 9 + ph))
    s /= sum(a_ for _, a_ in HAIR_STREAKS)
    img = bpy.data.images['head_albedo']
    w, hh = img.size
    px = np.array(img.pixels[:], np.float32).reshape(hh, w, 4)
    # not where the portrait itself is the texture (facing the view): its own curls are drawn there
    facing = (n * np.array(FWD, np.float32)).sum(-1)
    k = (hw * cov * (1 - np.clip((facing - PORTRAIT_FRONT[0]) / (PORTRAIT_FRONT[1] - PORTRAIT_FRONT[0]), 0, 1)))[..., None]
    # one hue for all the hair: the portrait's (the front, facing the view it was painted from); the generated back
    # came out red-brown
    rgb = px[..., :3]
    lum = np.maximum(rgb @ mat_util.LUM, 1e-4)
    chroma = rgb / lum[..., None]
    front = (hw > 0.9) & cov & (facing > 0.6)
    target = np.median(chroma[front], 0)
    chroma = chroma + (target - chroma) * (HAIR_HUE * k)
    skin = (hw < 0.5) & cov  # (the hairline too: the greenish cast sits at the temples)
    skin_hue = np.median(chroma[skin & (facing > 0.6)], 0)
    g = skin[..., None] * np.clip((chroma[..., 1:2] / np.maximum(chroma[..., 0:1], 1e-4) - SKIN_GREEN[0])
                                  / (SKIN_GREEN[1] - SKIN_GREEN[0]), 0, 1)
    chroma = chroma + (skin_hue - chroma) * g
    print('skin: %d greenish texels to the skin hue' % int((g[..., 0] > 0.5).sum()))
    # ... and no lighter than the portrait's hair (HAIR_MAX_L): where skin colour lay under what is hair (his left
    # sideburn) it came out a blond streak
    hl_max = float(np.median(lum[front])) * HAIR_MAX_L
    lum = lum + (np.minimum(lum, hl_max) - lum) * k[..., 0]
    rgb = chroma * lum[..., None]
    # the neck under the jaw: plain skin (projected and carried down, the picture's collar and the rim's colours ran
    # down it in stripes); no shadow painted in
    cut = CHIN_Z - NECK_CUT
    # ... and the skin under the chin's level facing down (the slope from the throat up under the jaw): fading out over
    # 1.2 cm under the cut, the bake's flecks of the beard's ends and its islands' dotted edges showed there
    down_ = np.clip((-n[..., 2] - 0.1) / 0.2, 0, 1) * np.clip((CHIN_Z - p[..., 2]) / 0.008, 0, 1)
    fade = np.maximum(np.clip((cut + NECK_PLAIN - p[..., 2]) / NECK_PLAIN, 0, 1), down_)
    fade = fade * np.clip((0.65 - hw) / 0.3, 0, 1) * cov  # soft at the hair's edge (cut at hw 0.5, its edge was a
    neck = fade > 0                                         # jagged step between plain and textured skin)
    sh = NECK_SHADE[1] + (NECK_SHADE[0] - NECK_SHADE[1]) * np.clip((cut - p[..., 2]) / (cut - NECK_Z0), 0, 1)
    skin_lum = float(np.median(lum[skin & (facing > 0.6)]))  # (in the picture's own encoding, like rgb)
    skin_rgb = skin_hue[None, None, :] * (skin_lum * sh)[..., None]
    rgb = np.where(neck[..., None], rgb + (skin_rgb - rgb) * fade[..., None], rgb)
    print('neck: %d texels plain skin' % int(neck.sum()))
    # under the nose (the nostrils, out of the picture's view): plain skin of the skin's brightness - the bake left the
    # picture's light from the nose's tip there, a pale yellow sheet with dark flecks
    box = cov & (np.abs(p[..., 0] - NOSE.x) < NOSE_UNDER[0]) & (p[..., 1] > NOSE.y - 0.01) & (
        p[..., 1] < NOSE.y + NOSE_UNDER[1]) & (p[..., 2] < NOSE.z + 0.004) & (p[..., 2] > NOSE.z - NOSE_UNDER[2])
    wn = box * np.clip((-n[..., 2] - 0.15) / 0.25, 0, 1) * (1 - hw)
    rgb = rgb + (skin_rgb - rgb) * wn[..., None]
    print('under the nose: %d texels plain skin (tip at %s)' % (int((wn > 0.5).sum()), tuple(round(x, 3) for x in NOSE)))
    # under the jaw and the beard (facing down, out of the picture's view): no paler than the skin (the hair) there -
    # the picture's white shirt collar and the generation's pale beard ends were stretched over them in light shards
    hair_lum = float(np.median(lum[(hw > 0.9) & cov & (facing > 0.6)]))
    under = cov & (n[..., 2] < -UNDER_JAW[0]) & (p[..., 2] < CHIN_Z + UNDER_JAW[2])
    du = np.clip((-n[..., 2] - UNDER_JAW[0]) / (UNDER_JAW[1] - UNDER_JAW[0]), 0, 1) * under
    cap = (skin_lum * (1 - hw) + hair_lum * hw) * UNDER_JAW_SHADE
    l_now = np.maximum(rgb @ mat_util.LUM, 1e-4)
    pale = np.clip(1 - (rgb.max(-1) - rgb.min(-1)) / np.maximum(rgb.max(-1), 1e-4) / 0.25, 0, 1)  # low chroma: white
    # ... and the throat under the chin whichever way it faces: the picture's shirt collar was projected onto it and
    # showed from below as a white sheet between the chin and the collar
    du = np.maximum(du, ((pale > 0.5) & cov & (p[..., 2] < CHIN_Z + UNDER_JAW[2]) & (hw < 0.5)).astype(du.dtype))
    tint = (skin_hue[None, None, :] * (1 - hw[..., None]) + target[None, None, :] * hw[..., None])
    fixed = np.where((pale > 0.5)[..., None], tint * np.minimum(l_now, cap)[..., None],
                     rgb * (np.minimum(l_now, cap) / l_now)[..., None])
    rgb = rgb + (fixed - rgb) * du[..., None]
    print('under the jaw: %d texels cleaned' % int((du > 0.5).sum()))
    # the beard's underside over the neck (the cut's cap, facing down): one plain colour, the hair's - the bake left
    # light rim colours and flecks there, a pale plank between the whiskers and the collar
    fl = (cov * np.clip((hw - 0.35) / 0.3, 0, 1) * np.clip((cut + NECK_PLAIN * 3 - p[..., 2]) / NECK_PLAIN, 0, 1)
          * np.clip((-n[..., 2] - UNDER_JAW[0]) / (UNDER_JAW[1] - UNDER_JAW[0]), 0, 1))
    rgb = rgb + (target[None, None, :] * hair_lum * UNDER_JAW_SHADE - rgb) * fl[..., None]
    print('beard underside: %d texels plain' % int((fl > 0.5).sum()))
    # where the neck meets the beard's and the jaw's underside, away from the picture's view: skin into hair by the hair
    # weight alone, each its plain colour - the bake left the source's jagged class edges there (a dark twig on the
    # neck's side) and its islands' edges in dotted lines
    zw = np.clip((cut + JOIN_PLAIN[1] - p[..., 2]) / (JOIN_PLAIN[1] - JOIN_PLAIN[0]), 0, 1) * cov
    zw = zw * (1 - np.clip((facing - 0.3) / 0.3, 0, 1))
    hk = np.clip((hw - 0.35) / 0.3, 0, 1)[..., None]
    plain = (skin_hue[None, None, :] * skin_lum) * (1 - hk) + (target[None, None, :] * hair_lum) * hk
    rgb = rgb + (plain - rgb) * zw[..., None]
    print('neck join: %d texels plain' % int((zw > 0.5).sum()))
    # behind the ears there is only the hair and the nape's skin: their hues by the hair weight, the light and the
    # strands kept (a red-brown patch of the generation's on his left nape came through everything else)
    bw = (np.clip((p[..., 1] - BACK_Y[0]) / (BACK_Y[1] - BACK_Y[0]), 0, 1) * cov)[..., None]
    back_hue = target[None, None, :] * hk + skin_hue[None, None, :] * (1 - hk)
    rgb = rgb + (back_hue * (rgb @ mat_util.LUM)[..., None] - rgb) * bw
    print('behind the ears: %d texels to the hair and skin hues' % int((bw[..., 0] > 0.5).sum()))
    px[..., :3] = np.clip(rgb * (1 + HAIR_CONTRAST * s[..., None] * k), 0, 1)
    # the islands padded out over the background and the bake's own margin (no dark rims on the small ones; the
    # margin kept the bake's raw colours, which the cleaning above never saw - pale dotted lines along the seams
    # under the jaw)
    px[..., :3] = mat_util.pad(px[..., :3], cov)
    img.pixels.foreach_set(px.ravel()); mat_util.write(img)
    height = s * k[..., 0] * HAIR_RELIEF
    nrm = mat_util.save('Head_Normal', mat_util.normals(height) * 0.5 + 0.5, HEAD_NORMAL, 'Non-Color')
    # roughness: skin SKIN_ROUGH, hair and beard HAIR_ROUGH (matt: one roughness for both, the beard's smoothed
    # underside shone like wet plastic from below)
    rough = (SKIN_ROUGH * (1 - hw) + HAIR_ROUGH * hw).astype(np.float32)
    mr = mat_util.save('Head_MR', np.stack([np.zeros_like(rough), rough, np.zeros_like(rough)], 2), HEAD_MR, 'Non-Color')
    mat_util.material('Head_Skin', img, mr, nrm)
    print('hair strands: %d texels' % int((hw > 0.5).sum()))


def ear_surroundings():
    """The ears cleaned in the baked texture: the generation's ear sits a little elsewhere than the portrait's and the
    bake picked between the sources face by face - flakes of hair colour on the ear's rim. Within EAR_RING[0] of the
    ear (head_ears) it is the portrait's skin a little redder (its fine light and dark kept a little), fading into
    what is there by EAR_RING[1] - per texel, and per vertex carried over its faces (the vertices are 2-4 mm apart:
    by the texel's distance to them alone, the middles of the bowl's faces kept the generation's dark shade and red
    streaks); those vertices count as skin (where the generation coloured them hair-dark, hair_detail() drew strands
    on the ear). The hair round the ears is left as it is."""
    kd = KDTree(len(HEAD_EAR_PTS))
    for i, q in enumerate(HEAD_EAR_PTS):
        kd.insert(q, i)
    kd.balance()
    me = head.data
    ring = lambda d: np.clip(1 - (d - EAR_RING[0]) / (EAR_RING[1] - EAR_RING[0]), 0, 1)  # noqa: E731
    wv = np.array([ring(kd.find(v.co)[2]) for v in me.vertices], np.float32)
    data, cov = mat_util.raster(me, TEX, wv[:, None])
    img = bpy.data.images['head_albedo']
    w_, hh = img.size
    px = np.array(img.pixels[:], np.float32).reshape(hh, w_, 4)
    rgb = px[..., :3]
    P = data[..., :3]
    cand = np.zeros(cov.shape, bool)
    for c in EAR_C:
        cand |= cov & (np.linalg.norm(P - np.array(c[:]), axis=-1) < 0.06)
    dist = np.full(cov.shape, 1.0, np.float32)
    for y, x in zip(*np.nonzero(cand)):
        dist[y, x] = kd.find(Vector(P[y, x].tolist()))[2]
    lum = rgb @ LUM
    detail = np.clip(lum / np.maximum(blur(lum, 4), 1e-4), 0.93, 1.07)[..., None]
    ear_col = np.clip(np.array(SKIN_SRGB) * np.array(EAR_TINT), 0, 1)  # the bake there is half hair-dark
    k = np.maximum(ring(dist), data[..., 6])[..., None] * cov[..., None]
    px[..., :3] = rgb * (1 - k) + np.clip(ear_col * detail, 0, 1) * k
    img.pixels.foreach_set(px.ravel()); mat_util.write(img)
    n = 0
    for hv in hb.verts:
        if kd.find(hv.co)[2] < EAR_RING[0]:
            HCLS[hv] = head_shape.SKIN
            n += 1
    print('ears: %d texels, %d vertices skin' % (int((k[..., 0] > 0.5).sum()), n))


ear_surroundings()
